java.util.Calendar calendar = java.util.Calendar.getInstance();
int months_ = PRNumberFormat.parseLocalizedAsInteger(null, myStepPage.getString(".CityID"));
int years_ = PRNumberFormat.parseLocalizedAsInteger(null, myStepPage.getString(".City"));
calendar.set(years_, months_ - 1, 1);
int days = calendar.getActualMaximum(java.util.Calendar.DAY_OF_MONTH);
ClipboardProperty attachStream = myStepPage.getProperty(".Keyword");
attachStream.setValue(days);
